#!/usr/bin/env node
import { readdirSync, readFileSync } from "node:fs";
import { relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const fixedSrcMaxLines = 800;
const fixedTestMaxLines = 1200;
const budgetFile = "scripts/web-file-length-budget.json";
const scanRoots = [
  { root: "apps/web/src", limitKey: "srcMaxLines" },
  { root: "apps/web/tests", limitKey: "testMaxLines" },
];
const scannedExtensions = new Set([".ts", ".vue"]);
// Generated Swagger client; regenerated by `pnpm run generate:api-types`,
// never edited by hand, so it must not consume ratchet budget.
const excludedPrefixes = ["apps/web/src/generated/"];

export function lineCount(contents) {
  return contents ? contents.split("\n").length - (contents.endsWith("\n") ? 1 : 0) : 0;
}

export function fileLengthLimit(path, budget) {
  return path.startsWith("apps/web/tests/") ? budget.testMaxLines : budget.srcMaxLines;
}

export function compareWebFileLengthBudget(files, budget) {
  const failures = [];
  if (budget.srcMaxLines !== fixedSrcMaxLines) {
    failures.push(`srcMaxLines must remain ${fixedSrcMaxLines}`);
  }
  if (budget.testMaxLines !== fixedTestMaxLines) {
    failures.push(`testMaxLines must remain ${fixedTestMaxLines}`);
  }
  const exceptions = budget.exceptions ?? {};
  const byName = new Map(files.map((file) => [file.name, file]));
  for (const file of files) {
    const limit = fileLengthLimit(file.name, budget);
    const exception = exceptions[file.name];
    if (file.lines <= limit) {
      if (exception !== undefined) {
        failures.push(`${file.name} has a stale exception at ${file.lines} lines`);
      }
      continue;
    }
    if (exception === undefined) {
      failures.push(`${file.name} has ${file.lines} lines, limit ${limit}`);
      continue;
    }
    if (!Number.isInteger(exception) || exception <= limit) {
      failures.push(`${file.name} exception must exceed ${limit}`);
    } else if (file.lines > exception) {
      failures.push(`${file.name} grew to ${file.lines} lines, budget ${exception}`);
    }
  }
  for (const name of Object.keys(exceptions)) {
    if (!byName.has(name)) failures.push(`${name} exception does not match a scanned file`);
  }
  return failures;
}

function fileExtension(path) {
  const index = path.lastIndexOf(".");
  return index >= 0 ? path.slice(index) : "";
}

function walk(directory) {
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const path = resolve(directory, entry.name);
    return entry.isDirectory() ? walk(path) : [path];
  });
}

function collectFiles(root) {
  return scanRoots.flatMap(({ root: scanRoot }) =>
    walk(resolve(root, scanRoot))
      .filter((path) => scannedExtensions.has(fileExtension(path)))
      .map((path) => relative(root, path).split(sep).join("/"))
      .filter((name) => !excludedPrefixes.some((prefix) => name.startsWith(prefix)))
      .map((name) => ({ name, lines: lineCount(readFileSync(resolve(root, name), "utf8")) })),
  );
}

function main() {
  const root = resolve(process.cwd());
  const budget = JSON.parse(readFileSync(resolve(root, budgetFile), "utf8"));
  const files = collectFiles(root);
  const failures = compareWebFileLengthBudget(files, budget);
  if (failures.length) {
    console.error("web file length budget regressed:");
    failures.forEach((failure) => console.error(`- ${failure}`));
    process.exitCode = 1;
    return;
  }
  const oversized = files.filter((file) => file.lines > fileLengthLimit(file.name, budget));
  console.log(
    `web file length budget passed: ${files.length} files scanned, `
    + `${oversized.length} frozen exceptions (src limit ${budget.srcMaxLines}, test limit ${budget.testMaxLines}).`,
  );
}

if (resolve(process.argv[1] || "") === fileURLToPath(import.meta.url)) main();
